import React from 'react'
import { AbsoluteFill, Audio, Easing, Img, interpolate, Sequence, staticFile, useCurrentFrame } from 'remotion'
import { Backdrop, bar, Brand, C, clamp, Cursor, DotCloud, Fade, Grain, inOut, lerp, LightLeak, MONO, Pill, PIXEL, Rise, SANS, Shot,
  Spoken, Spot, Subtitles, Vignette, Wipe } from './kit'
import { NUM, useBoxes, useCloud } from './data'
import { CUES } from './cues'

// length follows the narration (cues.ts, generated by score.py)
export const GUIDE_FRAMES = CUES.guide.frames
const L = CUES.guide.lines
const sec = (s: number) => Math.round(s * 30)
const TITLES = ['Install', 'Open a part', 'Read the feature map', 'Choose the analysis', 'Simplify & verify', 'Compare & export',
  'Ask in plain English', 'Batch, FreeCAD & results']
const CH = Object.values(L).filter((c) => c.chapter != null).sort((a, b) => a.s - b.s)
  .map((c, i, all) => ({ n: String(i + 1).padStart(2, '0'), t: TITLES[i], s: c.s, e: i + 1 < all.length ? all[i + 1].s : L.end.s }))

// default framing for app shots in the walkthrough: leaves room for subtitles
const W = 1380
const Y = -34

/** Sequence from absolute frame a to b; children see local frames. */
const Seg: React.FC<{ a: number; b: number; children: (dur: number, off: number) => React.ReactNode }> = ({ a, b, children }) => (
  <Sequence from={a} durationInFrames={Math.max(1, b - a)}>{children(b - a, a)}</Sequence>
)

export const Guide: React.FC = () => {
  const f = useCurrentFrame()
  const B = useBoxes()
  const cloud = useCloud('printer_chassis')
  const cur = CH.findIndex((c) => f >= c.s - 30 && f < c.e - 30)
  const box = (k: string) => B[k] ?? { x: 900, y: 500, width: 100, height: 40 }
  const rel = (c: { s: number }, t: number, off: number) => c.s - off + sec(t)

  return (
    <AbsoluteFill style={{ background: C.bg, fontFamily: SANS }}>
      <Audio src={staticFile('guide.wav')} />
      <Backdrop aura={0.85} tint="mix" />

      {/* ---- opening */}
      <Seg a={0} b={CH[0].s - 30}>{(dur) => (
        <>
          <DotCloud data={cloud} size={920} x={520} y={20} assemble={lerp(f, [sec(0.3), bar(2.6)], [0, 1], Easing.bezier(0.3, 0, 0.1, 1))}
            highlight={1} spin={-0.6 + f * 0.004} tilt={0.72} dot={1.5} opacity={interpolate(f, [dur - 24, dur], [1, 0], clamp)} />
          <AbsoluteFill style={{ padding: '0 0 0 150px', justifyContent: 'center' }}>
            <Brand at={10} size={50} />
            <div style={{ height: 34 }} />
            <Rise text="The walkthrough" at={30} size={120} out={dur - 20} />
            <div style={{ height: 36 }} />
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px 44px', width: 780 }}>
              {CH.map((c, i) => (
                <Fade key={c.n} at={L.hello.s + sec(4.2) + i * 4} out={dur - 20}>
                  <div style={{ fontSize: 28, color: C.ink2 }}><span style={{ fontFamily: PIXEL, color: C.orange, marginRight: 14 }}>{c.n}</span>{c.t}</div>
                </Fade>
              ))}
            </div>
          </AbsoluteFill>
        </>
      )}</Seg>

      {/* ---- 01 install */}
      <Seg a={CH[0].s + 16} b={CH[1].s - 30}>{(dur, off) => (
        <>
          <Terminal dur={dur} title="Terminal — macOS / Linux" lines={[
            { c: '$ git clone https://github.com/Harishik/defeat-cad && cd defeat-cad', t: rel(L.install, 1.4, off) - 14 },
            { c: '$ ./setup.sh', t: rel(L.install, 3.6, off) },
            { o: 'Installing OpenCASCADE · gmsh · scikit-fem · PyTorch Geometric …', t: rel(L.install, 5.6, off) },
            { o: '✓ Environment ready', t: rel(L.install, 8.6, off), ok: true },
            { c: '$ ./run.sh', t: rel(L.run, 2.4, off) },
            { o: 'DeFeat running at http://127.0.0.1:8000', t: rel(L.run, 3.4, off), ok: true },
          ]} />
          <Fade at={rel(L.run, 0.2, off)} out={dur - 14} style={{ position: 'absolute', right: 170, bottom: 150 }}>
            <div style={{ fontFamily: MONO, fontSize: 26, color: C.ink2, padding: '18px 24px', borderRadius: 16, border: `1px solid ${C.line}`,
              background: 'rgba(27,31,35,0.85)', backdropFilter: 'blur(14px)' }}>
              Windows → <span style={{ color: C.ink }}>setup.ps1</span>, then <span style={{ color: C.ink }}>run.bat</span>
            </div>
          </Fade>
        </>
      )}</Seg>

      {/* ---- 02 open a part */}
      <Seg a={CH[1].s + 16} b={L.samples.s - 6}>{(dur, off) => (
        <Shot src="welcome" dur={dur} width={W} from={{ ry: -14, rx: 6, z: -140, y: Y }} to={{ ry: -4, rx: 3, z: 0, y: Y }} zoom={[1, 1.12]} focus={[0.4, 0.62]}>
          <Spot b={box('welcome.command')} at={rel(L.open, 0.6, off)} label="Drop a STEP file, or describe a part" side="top" />
          <Cursor path={[{ t: 4, x: 1400, y: 300 }, { t: rel(L.open, 1.4, off), x: box('welcome.command').x + 140, y: box('welcome.command').y + 40, click: true }]} />
        </Shot>
      )}</Seg>
      <Seg a={L.samples.s - 6} b={CH[2].s - 30}>{(dur) => (
        <Shot src="welcome_cards" dur={dur} width={W} from={{ ry: 10, rx: 5, z: -120, y: Y }} to={{ ry: 3, rx: 2, z: 0, y: Y }} zoom={[1, 1.08]} focus={[0.5, 0.6]}>
          <Cursor path={[{ t: 6, x: 700, y: 400 }, { t: sec(1.2), x: 760, y: 620, click: true }, { t: dur, x: 1100, y: 640 }]} />
        </Shot>
      )}</Seg>

      {/* ---- 03 feature map */}
      <Seg a={CH[2].s + 16} b={L.isolate.s - 6}>{(dur, off) => (
        <Shot src="features" dur={dur} width={W} from={{ ry: -16, rx: 6, z: -160, y: Y }} to={{ ry: -6, rx: 3, z: 40, y: Y }} zoom={[1.0, 1.38]} focus={[0.97, 0.22]}>
          <Spot b={box('features.side')} at={rel(L.map, 1.2, off)} pad={2} out={rel(L.map, 4.6, off)} />
          <Spot b={box('features.frow')} at={rel(L.map, 5.2, off)} label="Reason + neural-network second opinion" side="left" pad={4} />
        </Shot>
      )}</Seg>
      <Seg a={L.isolate.s - 6} b={L.isolate.s + sec(2.6)}>{(dur, off) => (
        <Shot src="isolate_holes" dur={dur} width={W} from={{ ry: 8, rx: 5, z: -60, y: Y }} to={{ ry: 4, rx: 3, z: 0, y: Y }} zoom={[1, 1.1]} focus={[0.35, 0.9]} exit={false}>
          <Spot b={box('features.chips')} at={rel(L.isolate, 0.2, off)} pad={4} />
          <Cursor path={[{ t: 2, x: 900, y: 700 }, { t: rel(L.isolate, 0.5, off), x: box('features.chips').x + 160, y: box('features.chips').y + 18, click: true }]} />
        </Shot>
      )}</Seg>
      <Seg a={L.isolate.s + sec(2.6)} b={CH[3].s - 30}>{(dur) => (
        <Shot src="isolate" dur={dur} width={W} enter={false} from={{ ry: 4, rx: 3, z: 0, y: Y }} to={{ ry: -2, rx: 2, z: 60, y: Y }} zoom={[1.1, 1.22]} focus={[0.4, 0.62]} sheen={4} />
      )}</Seg>

      {/* ---- 04 analysis */}
      <Seg a={CH[3].s + 16} b={CH[4].s - 30}>{(dur, off) => (
        <Shot src="features" dur={dur} width={W} from={{ ry: 12, rx: 6, z: -140, y: Y }} to={{ ry: 4, rx: 3, z: 0, y: Y }} zoom={[1.4, 1.62]} focus={[0.66, 0.02]}>
          <Spot b={box('features.presets')} at={rel(L.choose, 1.0, off)} label="Static · Modal · Thermal · CFD" side="left" pad={4} out={rel(L.h, 0.2, off)} />
          <Spot b={box('features.h')} at={rel(L.h, 0.6, off)} label="Target mesh size h" side="left" pad={4} />
          <Cursor path={[{ t: 6, x: 900, y: 300 }, { t: rel(L.choose, 1.6, off), x: box('features.presets').x + 70, y: box('features.presets').y + 18, click: true },
            { t: rel(L.h, 0.8, off), x: box('features.h').x + 60, y: box('features.h').y + 16, click: true }]} />
        </Shot>
      )}</Seg>

      {/* ---- 05 simplify & verify */}
      <Seg a={CH[4].s + 16} b={L.simplify.s + sec(2.2)}>{(dur, off) => (
        <Shot src="features" dur={dur} width={W} from={{ ry: -10, rx: 5, z: -100, y: Y }} to={{ ry: -6, rx: 3, z: 0, y: Y }} zoom={[1.3, 1.5]} focus={[0.98, 0.02]} exit={false}>
          <Spot b={box('features.run')} at={rel(L.simplify, 0.3, off)} pad={4} />
          <Cursor path={[{ t: 4, x: 1300, y: 300 }, { t: rel(L.simplify, 0.5, off), x: box('features.run').x + 50, y: box('features.run').y + 18, click: true }]} />
        </Shot>
      )}</Seg>
      <Seg a={L.simplify.s + sec(2.2)} b={L.verify.s - 6}>{(dur) => (
        <Shot src="loader" dur={dur} width={W} enter={false} from={{ ry: -6, rx: 3, z: 0, y: Y }} to={{ ry: 2, rx: 2, z: 40, y: Y }} zoom={[1.05, 1.25]} focus={[0.5, 0.5]} sheen={6} />
      )}</Seg>
      <Seg a={L.verify.s - 6} b={L.guard.s - 6}>{(dur, off) => (
        <Shot src="results" dur={dur} width={W} from={{ ry: 12, rx: 5, z: -120, y: Y }} to={{ ry: 4, rx: 3, z: 0, y: Y }} zoom={[1.0, 1.3]} focus={[0.02, 0.3]}>
          <Spot b={box('results.stats')} at={rel(L.verify, 2.4, off)} pad={6} out={rel(L.verify, 5.0, off)} />
          <Spot b={box('results.fea')} at={rel(L.verify, 5.2, off)} pad={6} />
        </Shot>
      )}</Seg>
      <Seg a={L.guard.s - 6} b={CH[5].s - 30}>{(dur, off) => <Guard dur={dur} off={off} />}</Seg>

      {/* ---- 06 compare & export */}
      <Seg a={CH[5].s + 16} b={L.export.s - 6}>{(dur) => (
        <Wipe a="view_original" b="view_simplified" dur={dur} width={W} from={{ ry: 12, rx: 5, z: -120, y: Y }} to={{ ry: -4, rx: 3, z: 0, y: Y }} />
      )}</Seg>
      <Seg a={L.export.s - 6} b={L.export.s + sec(5.0)}>{(dur, off) => (
        <Shot src="results" dur={dur} width={W} from={{ ry: -10, rx: 5, z: -100, y: Y }} to={{ ry: -4, rx: 3, z: 0, y: Y }} zoom={[1.2, 1.45]} focus={[0.02, 0.75]}>
          <Spot b={box('results.dl')} at={rel(L.export, 1.4, off)} pad={6} />
          <Spot b={box('results.code')} at={rel(L.export, 3.6, off)} pad={6} />
          <Cursor path={[{ t: 4, x: 900, y: 500 }, { t: rel(L.export, 2.0, off), x: box('results.dl').x + 60, y: box('results.dl').y + 20, click: true }]} />
        </Shot>
      )}</Seg>
      <Seg a={L.export.s + sec(5.0)} b={CH[6].s - 30}>{(dur) => (
        <Shot src="report" dur={dur} width={W} from={{ ry: 8, rx: 5, z: -100, y: Y }} to={{ ry: 2, rx: 2, z: 20, y: Y }} zoom={[1, 1.1]} focus={[0.5, 0.2]} />
      )}</Seg>

      {/* ---- 07 assistant */}
      <Seg a={CH[6].s + 16} b={L.ask.s + sec(3.2)}>{(dur, off) => (
        <Shot src="chat_typed" dur={dur} width={W} from={{ ry: -12, rx: 5, z: -120, y: Y }} to={{ ry: -6, rx: 3, z: 0, y: Y }} zoom={[1.1, 1.3]} focus={[0.95, 0.88]} exit={false}>
          <Spot b={box('chat.input')} at={rel(L.ask, 1.0, off)} label="Plain English · local model" side="top" pad={4} />
        </Shot>
      )}</Seg>
      <Seg a={L.ask.s + sec(3.2)} b={L.cmdk.s - 6}>{(dur) => (
        <Shot src="chat_reply" dur={dur} width={W} enter={false} from={{ ry: -6, rx: 3, z: 0, y: Y }} to={{ ry: -2, rx: 2, z: 40, y: Y }} zoom={[1.55, 1.75]} focus={[0.97, 0.3]} sheen={6} />
      )}</Seg>
      <Seg a={L.cmdk.s - 6} b={CH[7].s - 30}>{(dur) => (
        <Shot src="cmdk" dur={dur} width={W} from={{ ry: 10, rx: 6, z: -140, y: Y }} to={{ ry: 2, rx: 2, z: 0, y: Y }} zoom={[1, 1.2]} focus={[0.5, 0.22]}>
          <Kbd at={8} />
        </Shot>
      )}</Seg>

      {/* ---- 08 batch, FreeCAD, proof */}
      <Seg a={CH[7].s + 16} b={L.batch.s + sec(4.2)}>{(dur, off) => (
        <Terminal dur={dur} title="Batch mode" lines={[
          { c: '$ python -m defeat.cli parts/*.step --preset static --out out/', t: rel(L.batch, 0.3, off) - 16 },
          { o: 'l_bracket.step        16/25 removed   faces 84→36    tets −26%', t: rel(L.batch, 1.9, off) },
          { o: 'printer_chassis.step  11/31 removed   faces 261→168  tets −29%', t: rel(L.batch, 2.4, off) },
          { o: '✓ STEP · report · Python · C++ for every part', t: rel(L.batch, 2.9, off), ok: true },
        ]} />
      )}</Seg>
      <Seg a={L.batch.s + sec(4.2)} b={L.bench.s - 6}>{(dur) => <FreeCad dur={dur} />}</Seg>
      <Seg a={L.bench.s - 6} b={L.end.s - 30}>{(dur, off) => <Bars dur={dur} off={off} />}</Seg>

      {/* ---- outro */}
      <Seg a={L.end.s - 30} b={GUIDE_FRAMES}>{(dur) => (
        <>
          <DotCloud data={cloud} size={820} y={-110} assemble={lerp(f, [L.end.s - 30, L.end.s + 50], [0, 1], Easing.bezier(0.3, 0, 0.1, 1))}
            dissolve={1} highlight={0} spin={-0.6 + f * 0.003} tilt={0.72} dot={1.4} glow={0} />
          <AbsoluteFill style={{ justifyContent: 'flex-end', alignItems: 'center', paddingBottom: 160 }}>
            <Brand at={26} size={80} glow={lerp(f, [L.end.s, L.end.s + 30, L.end.s + 90], [0, 1, 0.4])} />
            <div style={{ height: 24 }} />
            <Spoken cue={{ ...L.end, s: 30, e: 30 + L.end.e - L.end.s }} text="Step in. Simulation-ready step out. Checked." size={40} weight={400} color={C.ink2} align="center" highlight={['Checked']} />
          </AbsoluteFill>
        </>
      )}</Seg>

      {/* chapter cards, rail and transitions */}
      {CH.map((c, i) => <ChapterCard key={c.n} i={i} />)}
      {cur >= 0 && (
        <div style={{ position: 'absolute', left: 160, right: 160, top: 30, display: 'flex', gap: 10 }}>
          {CH.map((c, i) => {
            const p = i < cur ? 1 : i > cur ? 0 : interpolate(f, [c.s - 30, c.e - 30], [0, 1], clamp)
            return (
              <div key={c.n} style={{ flex: c.e - c.s, height: 3, borderRadius: 2, background: C.line, overflow: 'hidden' }}>
                <div style={{ width: `${p * 100}%`, height: '100%', background: i === cur ? C.orange : C.ink3 }} />
              </div>
            )
          })}
        </div>
      )}
      {CH.map((c) => <LightLeak key={c.n} at={c.s - 30} dur={22} hue={Number(c.n) % 2 ? 'orange' : 'royal'} x={30} />)}
      <LightLeak at={L.end.s} dur={30} hue="white" />
      <Subtitles cues={Object.fromEntries(Object.entries(L).filter(([k]) => k !== 'end'))} />
      <Vignette strength={0.6} />
      <AbsoluteFill style={{ background: '#000', opacity: interpolate(f, [GUIDE_FRAMES - 40, GUIDE_FRAMES - 4], [0, 1], clamp) }} />
      <Grain opacity={0.06} />
    </AbsoluteFill>
  )
}

/** Full-screen chapter card around the start of a chapter, then a small label in the corner for the rest of it. */
const ChapterCard: React.FC<{ i: number }> = ({ i }) => {
  const c = CH[i]
  const f = useCurrentFrame()
  if (f < c.s - 34 || f >= c.e - 30) return null
  const a = c.s - 34
  const out = lerp(f, [c.s + 8, c.s + 22], [0, 1], Easing.in(Easing.cubic))
  return (
    <>
      {f < c.s + 24 && (
        <AbsoluteFill style={{ justifyContent: 'center', padding: '0 170px', opacity: 1 - out, transform: `scale(${1 + out * 0.04})`, filter: `blur(${out * 10}px)`,
          background: `radial-gradient(70% 70% at 30% 50%, rgba(14,16,19,${0.85 * (1 - out)}), rgba(14,16,19,${0.6 * (1 - out)}))` }}>
          <Rise text={c.n} at={a} size={220} font={PIXEL} color={C.orange} tracking={0} />
          <Rise text={c.t} at={a + 5} size={110} />
        </AbsoluteFill>
      )}
      {f >= c.s + 14 && (
        <div style={{ position: 'absolute', left: 160, top: 48, display: 'flex', gap: 16, alignItems: 'baseline', opacity: lerp(f, [c.s + 14, c.s + 30], [0, 1]) }}>
          <span style={{ fontFamily: PIXEL, fontSize: 28, color: C.orange }}>{c.n}</span>
          <span style={{ fontSize: 26, color: C.ink, fontWeight: 500 }}>{c.t}</span>
        </div>
      )}
    </>
  )
}

type Line = { c?: string; o?: string; t: number; ok?: boolean }
const Terminal: React.FC<{ dur: number; title: string; lines: Line[] }> = ({ dur, title, lines }) => {
  const f = useCurrentFrame()
  const p = lerp(f, [0, 24], [0, 1])
  const out = lerp(f, [dur - 14, dur], [0, 1], Easing.in(Easing.cubic))
  const ry = lerp(f, [0, dur], [-10, -3], inOut)
  const shown = lines.filter((x) => f >= x.t).length
  return (
    <AbsoluteFill style={{ perspective: 2200 }}>
      <div style={{ position: 'absolute', left: 190, right: 190, top: 180, borderRadius: 24, overflow: 'hidden', opacity: p * (1 - out),
        transform: `translateZ(${-(1 - p) * 240 - out * 200}px) rotateY(${ry}deg) rotateX(${(1 - p) * 12 + 3}deg)`, filter: `blur(${(1 - p) * 12 + out * 8}px)`,
        background: 'rgba(22,25,29,0.94)', border: `1px solid ${C.line}`, boxShadow: '0 60px 160px rgba(0,0,0,0.65), inset 0 1px 0 rgba(255,255,255,0.06)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '16px 22px', borderBottom: `1px solid ${C.line}` }}>
          {['#ff5f57', '#febc2e', '#28c840'].map((c) => <span key={c} style={{ width: 14, height: 14, borderRadius: 7, background: c }} />)}
          <span style={{ marginLeft: 16, fontFamily: MONO, fontSize: 22, color: C.ink3 }}>{title}</span>
        </div>
        <div style={{ padding: '28px 32px', fontFamily: MONO, fontSize: 28, lineHeight: 1.75, minHeight: 360 }}>
          {lines.map((l, i) => {
            if (f < l.t) return null
            if (l.c) {
              const n = Math.floor(interpolate(f, [l.t, l.t + Math.max(10, l.c.length * 0.7)], [0, l.c.length], clamp))
              const caret = n < l.c.length || Math.floor(f / 15) % 2 === 0
              return <div key={i} style={{ color: C.ink }}>{l.c.slice(0, n)}{caret && i === shown - 1 ? <span style={{ color: C.orange }}>▋</span> : null}</div>
            }
            const o = lerp(f, [l.t, l.t + 8], [0, 1])
            return <div key={i} style={{ color: l.ok ? C.green : C.ink2, whiteSpace: 'pre', opacity: o }}>{l.o}</div>
          })}
        </div>
      </div>
    </AbsoluteFill>
  )
}

const Kbd: React.FC<{ at: number }> = ({ at }) => {
  const f = useCurrentFrame()
  const p = lerp(f, [at, at + 14], [0, 1])
  const press = f >= at + 20 && f < at + 28
  const key = (t: string) => (
    <div style={{ minWidth: 92, height: 92, padding: '0 22px', borderRadius: 20, background: 'linear-gradient(#2a2f35, #1c2024)', border: '1px solid rgba(255,255,255,0.12)',
      boxShadow: press ? '0 2px 0 #0b0d0f' : '0 8px 0 #0b0d0f, 0 20px 40px rgba(0,0,0,0.5)', transform: `translateY(${press ? 6 : 0}px)`,
      display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: SANS, fontSize: 44, fontWeight: 500, color: C.ink }}>{t}</div>
  )
  return (
    <div style={{ position: 'absolute', right: '6%', bottom: '10%', display: 'flex', gap: 16, opacity: p, transform: `translateY(${(1 - p) * 20}px)` }}>
      {key('⌘')}{key('K')}
    </div>
  )
}

const Guard: React.FC<{ dur: number; off: number }> = ({ dur, off }) => {
  const f = useCurrentFrame()
  const s = L.guard.s - off
  const g = lerp(f, [s + 6, s + 26], [0, 1])
  const restored = lerp(f, [s + sec(4.4), s + sec(5.4)], [0, 1], inOut)
  const out = lerp(f, [dur - 14, dur], [0, 1])
  return (
    <AbsoluteFill style={{ justifyContent: 'center', alignItems: 'center', opacity: 1 - out }}>
      <div style={{ display: 'flex', gap: 90, alignItems: 'center', marginTop: -40 }}>
        <div style={{ width: 760 }}>
          <Pill>Stress guard</Pill>
          <div style={{ height: 30 }} />
          <Spoken cue={{ ...L.guard, s, e: L.guard.e - off }} text="More than five percent? Features come back." size={66} highlight={['five', 'percent?']} />
        </div>
        <div style={{ width: 520, padding: '30px 34px', borderRadius: 26, background: 'rgba(20,23,27,0.85)', border: `1px solid ${C.line}`, backdropFilter: 'blur(20px)',
          boxShadow: '0 40px 120px rgba(0,0,0,0.6)', opacity: g, transform: `perspective(1600px) rotateY(${(1 - g) * -24 - 8}deg) translateZ(${(1 - g) * -120}px)` }}>
          {[['Before guard', '6.6%', C.orange, 66], ['After guard', '4.0%', C.green, 40]].map(([l, v, col, w], i) => {
            const show = i === 0 ? 1 : restored
            return (
              <div key={l as string} style={{ marginBottom: i === 0 ? 26 : 0, opacity: 0.25 + 0.75 * show }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
                  <span style={{ fontFamily: MONO, fontSize: 22, color: C.ink3 }}>{l} · worst load case</span>
                  <span style={{ fontFamily: PIXEL, fontSize: 60, color: col as string }}>{v}</span>
                </div>
                <div style={{ height: 8, borderRadius: 4, background: C.line, marginTop: 10, overflow: 'hidden' }}>
                  <div style={{ width: `${(w as number) * show}%`, height: '100%', background: col as string }} />
                </div>
              </div>
            )
          })}
          <div style={{ marginTop: 24, fontSize: 24, color: C.ink2, opacity: restored }}>Printer chassis: 10 of 21 features put back, automatically</div>
        </div>
      </div>
    </AbsoluteFill>
  )
}

const FreeCad: React.FC<{ dur: number }> = ({ dur }) => {
  const f = useCurrentFrame()
  const p = lerp(f, [0, 24], [0, 1])
  const out = lerp(f, [dur - 14, dur], [0, 1], Easing.in(Easing.cubic))
  const ry = lerp(f, [0, dur], [12, 4], inOut)
  const tree = ['Bracket (hidden)', 'Bracket_defeatured']
  return (
    <AbsoluteFill style={{ perspective: 2200 }}>
      <div style={{ position: 'absolute', left: 240, right: 240, top: 150, bottom: 200, borderRadius: 22, overflow: 'hidden', opacity: p * (1 - out),
        transform: `translateZ(${-(1 - p) * 220 - out * 200}px) rotateY(${ry}deg) rotateX(4deg)`, filter: `blur(${(1 - p) * 12 + out * 8}px)`,
        background: '#1b1e22', border: `1px solid ${C.line}`, boxShadow: '0 60px 160px rgba(0,0,0,0.65)', display: 'flex', flexDirection: 'column' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '14px 20px', borderBottom: `1px solid ${C.line}` }}>
          {['#ff5f57', '#febc2e', '#28c840'].map((c) => <span key={c} style={{ width: 13, height: 13, borderRadius: 7, background: c }} />)}
          <span style={{ marginLeft: 16, fontFamily: MONO, fontSize: 20, color: C.ink3 }}>FreeCAD 1.1 — Macro › DeFeat</span>
        </div>
        <div style={{ flex: 1, display: 'flex' }}>
          <div style={{ width: 360, borderRight: `1px solid ${C.line}`, padding: '22px 20px', fontFamily: SANS, fontSize: 22, color: C.ink2 }}>
            <div style={{ fontFamily: MONO, fontSize: 18, color: C.ink3, marginBottom: 14 }}>MODEL</div>
            {tree.map((t, i) => (
              <Fade key={t} at={10 + i * 18}><div style={{ padding: '8px 10px', borderRadius: 8, marginBottom: 6, color: i ? C.ink : C.ink3,
                background: i ? 'rgba(251,86,7,0.14)' : 'transparent', border: i ? '1px solid rgba(251,86,7,0.4)' : '1px solid transparent' }}>{t}</div></Fade>
            ))}
            <Fade at={50}><div style={{ marginTop: 26, fontFamily: MONO, fontSize: 17, lineHeight: 1.6, color: C.ink3 }}>
              DeFeat: 16 features removed<br />faces 84 → 36<br />mesh elements −26%<br /><span style={{ color: C.green }}>valid solid ✓</span>
            </div></Fade>
          </div>
          <div style={{ flex: 1, position: 'relative', background: '#1e1e1e' }}>
            <Img src={staticFile('shots/freecad_view.png')} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover',
              transform: `scale(${lerp(f, [0, dur], [1.05, 1.18], inOut)})` }} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  )
}

const Bars: React.FC<{ dur: number; off: number }> = ({ dur, off }) => {
  const f = useCurrentFrame()
  const s = L.bench.s - off
  const rows = [
    { l: 'Fillets found · F1 on 3,000 real designer parts', a: 0.69, b: NUM.filletF1 },
    { l: 'Chamfers found · F1', a: 0.58, b: NUM.chamferF1 },
    { l: 'Feature vs body · F1 on 3,122 MFCAD parts', a: 0.95, b: NUM.mfcadF1 },
    { l: `Valid solids out · ${NUM.parts} real parts`, a: 1.0, b: NUM.valid / 100 },
  ]
  const out = interpolate(f, [dur - 14, dur], [1, 0], clamp)
  return (
    <AbsoluteFill style={{ padding: '150px 190px 170px', justifyContent: 'center', opacity: out }}>
      <Fade at={s - 4}><Pill>Held-out benchmarks · real-world CAD</Pill></Fade>
      <div style={{ height: 46 }} />
      {rows.map((r, i) => {
        const at = s + sec(1.0) + i * sec(1.5)
        const p = lerp(f, [at, at + 28], [0, 1])
        return (
          <div key={r.l} style={{ marginBottom: 36, opacity: Math.min(p * 2, 1) }}>
            <div style={{ fontSize: 30, color: C.ink, marginBottom: 12 }}>{r.l}</div>
            <div style={{ position: 'relative', height: 32 }}>
              <div style={{ position: 'absolute', height: 10, top: 0, width: `${r.a * 68 * p}%`, background: '#3a4048', borderRadius: 5 }} />
              <div style={{ position: 'absolute', height: 14, top: 15, width: `${r.b * 68 * p}%`, background: C.orange, borderRadius: 7, boxShadow: '0 0 24px rgba(251,86,7,0.45)' }} />
              <span style={{ position: 'absolute', left: `calc(${r.b * 68 * p}% + 18px)`, top: -2, fontFamily: PIXEL, fontSize: 38, color: C.orange }}>{(r.b * p).toFixed(2)}</span>
            </div>
          </div>
        )
      })}
      <Fade at={s + sec(7)}><div style={{ fontFamily: MONO, fontSize: 22, color: C.ink3 }}>grey = rules only · orange = DeFeat (rules + neural network)</div></Fade>
    </AbsoluteFill>
  )
}
